    public static BrandProfileModel? Find(string slug) =>
        All.FirstOrDefault(brand =>
            string.Equals(brand.Slug, slug, StringComparison.OrdinalIgnoreCase));

    private static BrandProfileModel Brand(
        string slug,
        string name,
        string persianName,
        string? logoFile,
        string summary,
        string focus,
        string firstHighlight,
        string secondHighlight,
        string thirdHighlight) =>
        new(slug, name, persianName, logoFile, summary, focus,
            [firstHighlight, secondHighlight, thirdHighlight]);
